def _get_insert_token(token):
    """Returns either a whitespace or the line breaks from token."""
    # See issue484 why line breaks should be preserved.
    m = re.search(r'((\r\n|\r|\n)+) *$', token.value)
    if m is not None:
        return sql.Token(T.Whitespace.Newline, m.groups()[0])
    else:
        return sql.Token(T.Whitespace, ' ')

def _slices_from_text(self, text):
    last_break = 0
    for match in self._lang_vars.period_context_re().finditer(text):
        context = match.group() + match.group("after_tok")
        if self.text_contains_sentbreak(context):
            yield slice(last_break, match.end())
            if match.group("next_tok"):
                # next sentence starts after whitespace
                last_break = match.start("next_tok")
            else:
                # next sentence starts at following punctuation
                last_break = match.end()
    # The last sentence should not contain trailing whitespace.
    yield slice(last_break, len(text.rstrip()))

def import_requirements(project, r=None, dev=False):
    from pipenv.patched.notpip._vendor import requests as pip_requests
    from pipenv.patched.notpip._internal.req.constructors import install_req_from_parsed_requirement
    from pipenv.vendor.pip_shims.shims import parse_requirements

    # Parse requirements.txt file with Pip's parser.
    # Pip requires a `PipSession` which is a subclass of requests.Session.
    # Since we're not making any network calls, it's initialized to nothing.
    if r:
        assert os.path.isfile(r)
    # Default path, if none is provided.
    if r is None:
        r = project.requirements_location
    with open(r) as f:
        contents = f.read()
    indexes = []
    trusted_hosts = []
    # Find and add extra indexes.
    for line in contents.split("\n"):
        index, extra_index, trusted_host, _ = parse_indexes(line.strip(), strict=True)
        if index:
            indexes = [index]
        if extra_index:
            indexes.append(extra_index)
        if trusted_host:
            trusted_hosts.append(trusted_host)
    indexes = sorted(set(indexes))
    trusted_hosts = sorted(set(trusted_hosts))
    reqs = [install_req_from_parsed_requirement(f) for f in parse_requirements(r, session=pip_requests)]
    for package in reqs:
        if package.name not in BAD_PACKAGES:
            if package.link is not None:
                package_string = (
                    f"-e {package.link}"
                    if package.editable
                    else str(package.link)
                )
                project.add_package_to_pipfile(package_string, dev=dev)
            else:
                project.add_package_to_pipfile(str(package.req), dev=dev)
    for index in indexes:
        trusted = index in trusted_hosts
        project.add_index_to_pipfile(index, verify_ssl=trusted)
    project.recase_pipfile()

def get(self, ip):
    t1 = time.time()
    self.valid_args(ip)

    # Iterate through nameservers so that we can tell which one gets used.
    nameservers = current_app.config['RESOLVERS']
    for nameserver in nameservers:
        dns_resolver.nameservers = [nameserver]
        try:
            # http://stackoverflow.com/a/19867936/1707152
            answer = dns_resolver.query(
                reversename.from_address(ip), rdatatype.PTR,
                raise_on_no_answer=False)
            # Successful query
            break
        except Timeout as e:
            # Communication fail or timeout - try next nameserver
            if nameserver is nameservers[-1]:
                current_app.logger.info(e)
                return {'message': 'All nameservers timed out.'}, 503
            continue
        except NXDOMAIN:
            return {'message': 'No nameserver found for %s' % ip}, 404
        except Exception as e:
            current_app.logger.error(e)
            return {'message': 'An unexpected error occured.'}, 500

    t2 = time.time()
    duration = t2 - t1

    if answer is None:
        return {'message': 'An unexpected error occured.'}, 500
    return parse_query(answer, nameserver, duration)

